/// T2263: one render-only replay of `0x3C440`'s render half after the lifted frame returned. `r.esp` is the caller's esp
/// after the frame (entry + 4); the frame's own registers are rebuilt (ebx 0, ebp 0x20000000, five saved words below
/// the return slot) and the body runs on the dead stack below. The frame scratch arena bump pointer is rewound to its value
/// at the end of the frame before and after, so every replay reuses the same arena space. Registers are restored after.
pub fn render_half_replay<M: GuestMemory, C: GuestCall>(m: &mut M, guest: &mut C, r: &mut ExtRegisters) {
    let saved = *r;
    let arena_bump = m.read32(FRAME_ARENA_BUMP);
    r.esp = saved.esp.wrapping_sub(4 + 5 * 4);
    r.ebx = 0;
    r.ebp = 0x2000_0000;
    game_frame_render_half(m, guest, r);
    m.write32(FRAME_ARENA_BUMP, arena_bump);
    *r = saved;
}

/// # Safety
/// `regs` is a live `ExtRegisters`, `offset` maps the guest window, `call` is the trampoline (`src/host/render_rate.c`).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn tsfp_render_half_replay(regs: *mut ExtRegisters, offset: usize, call: crate::ext::CallFn) {
    let mut memory = unsafe { crate::memory::MappedGuest::new(offset) };
    let mut guest = KeepFrameRegister(crate::ext::CGuest(call));
    render_half_replay(&mut memory, &mut guest, unsafe { &mut *regs });
}

/// T2269: the lifted ABI models ebp as a function local, so a nested lifted callee can return with `g_ebp` (and therefore
/// `regs.ebp`) changed (MEASURED: the replay took the inverted `[0x7DE458] & ebp` branches, walking unset player cameras in
/// load frames, null matrix in 0x1530E0). The original treats ebp as callee-saved; this adapter restores it after each call.
struct KeepFrameRegister<C: GuestCall>(C);

impl<C: GuestCall> GuestCall for KeepFrameRegister<C> {
    fn call(&mut self, va: u32, regs: &mut ExtRegisters) {
        let ebp = regs.ebp;
        self.0.call(va, regs);
        regs.ebp = ebp;
    }
}
